export class AppComponent {

    private readonly myTourService = inject(MyTourService);
    
    constructor() {
        this.myTourService.start([{
            anchorId: 'start-tour',
            title: 'Welcome',
            content: 'Welcome to the Ngx-UI-Tour tour!'
        }]);
    }

}
